import java.util.*;

class Solution {
  public boolean canTraverseAllPairs(int[] nums) {
    int n = nums.length;
    if (n == 1) return true;
    DSU d = new DSU(n);
    Map<Integer, Integer> owner = new HashMap<>();
    for (int i = 0; i < n; i++) {
      int x = nums[i];
      for (int p = 2; p * p <= x; p++)
        if (x % p == 0) {
          Integer j = owner.putIfAbsent(p, i);
          if (j != null) d.union(i, j);
          while (x % p == 0) x /= p;
        }
      if (x > 1) {
        Integer j = owner.putIfAbsent(x, i);
        if (j != null) d.union(i, j);
      }
    }
    int root = d.find(0);
    for (int i = 1; i < n; i++) if (d.find(i) != root) return false;
    return true;
  }

  static class DSU {
    int[] p;

    DSU(int n) {
      p = new int[n];
      for (int i = 0; i < n; i++) p[i] = i;
    }

    int find(int x) {
      return p[x] == x ? x : (p[x] = find(p[x]));
    }

    void union(int a, int b) {
      p[find(a)] = find(b);
    }
  }
}
